BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(9);


DELETE FROM public.memberships WHERE group_id='39810000-0000-4000-8000-000000000002' AND user_id='39800000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub='39800000-0000-4000-8000-000000000001';
SELECT public.share_visit_to_group_v5('39830000-0000-4000-8000-000000000001','39810000-0000-4000-8000-000000000002',false,false,false);
SELECT lives_ok($$SELECT public.update_visit_v1('39810000-0000-4000-8000-000000000002','39830000-0000-4000-8000-000000000001','2026-09-21','lunch',ARRAY['39800000-0000-4000-8000-000000000001']::uuid[])$$,'Registrar edits from shared group');
SELECT throws_ok($$SELECT public.update_visit_v1('39810000-0000-4000-8000-000000000002','39830000-0000-4000-8000-000000000001','2026-09-21','lunch',ARRAY['39800000-0000-4000-8000-000000000001']::uuid[],_guests=>'[{"name":"Hidden guest"}]'::jsonb)$$,'P0001','Gäster kan bara redigeras från originalgruppen','Shared group cannot create private guests');
SELECT throws_ok($$SELECT public.update_visit_v1('39810000-0000-4000-8000-000000000002','39830000-0000-4000-8000-000000000001','2026-09-21','lunch',ARRAY['39800000-0000-4000-8000-000000000001']::uuid[],_removed_guest_ids=>ARRAY['39860000-0000-4000-8000-000000000001']::uuid[])$$,'P0001','Gäster kan bara redigeras från originalgruppen','Shared group cannot remove private guests');
RESET ROLE;
SELECT is((SELECT visited_on FROM public.visits WHERE id='39830000-0000-4000-8000-000000000001'),'2026-09-21'::date,'Same canonical visit corrected');
SELECT ok(EXISTS(SELECT 1 FROM public.visit_participants WHERE visit_id='39830000-0000-4000-8000-000000000001' AND user_id='39800000-0000-4000-8000-000000000002'),'Participant outside current group preserved');
SELECT is((SELECT display_name FROM public.visit_guests WHERE id='39860000-0000-4000-8000-000000000001'),'Privat gäst','Private guest preserved');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub='39800000-0000-4000-8000-000000000003';
SELECT throws_ok($$SELECT public.update_visit_v1('39810000-0000-4000-8000-000000000002','39830000-0000-4000-8000-000000000001','2026-09-21','lunch',ARRAY['39800000-0000-4000-8000-000000000001']::uuid[])$$,'P0001','Bara den som registrerade besöket kan redigera det','Recipient owner is not registrar');
SET LOCAL request.jwt.claim.sub='39800000-0000-4000-8000-000000000001';
SELECT throws_ok($$SELECT public.update_visit_v1('39810000-0000-4000-8000-000000000003','39830000-0000-4000-8000-000000000001','2026-09-21','lunch',ARRAY['39800000-0000-4000-8000-000000000001']::uuid[])$$,'P0001','Besöket finns inte i gruppen','Membership alone cannot edit an unlinked visit');
RESET ROLE;
DELETE FROM public.memberships WHERE group_id='39810000-0000-4000-8000-000000000002' AND user_id='39800000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub='39800000-0000-4000-8000-000000000001';
SELECT throws_ok($$SELECT public.update_visit_v1('39810000-0000-4000-8000-000000000002','39830000-0000-4000-8000-000000000001','2026-09-21','lunch',ARRAY['39800000-0000-4000-8000-000000000001']::uuid[])$$,'P0001','Du är inte aktiv medlem i gruppen','Former member cannot edit');
SELECT * FROM finish();
ROLLBACK;
